import hashlib
import secrets


def resolve_request_password_reset(
    _root,
    _info,
    username: str,
) -> dict:
    # CWE-640 fix: Replaced the predictable MD5 hash of the username with a cryptographically strong,
    # unpredictable token generated by secrets.token_urlsafe().
    # The original implementation allowed an attacker to guess or pre-compute reset tokens if they knew the username,
    # as MD5 is not suitable for generating unpredictable tokens and solely using the username as input made it trivial to reproduce.
    # secrets.token_urlsafe(32) generates a random, URL-safe text string of 32 bytes entropy,
    # which is suitable for a secure password reset token.
    token = secrets.token_urlsafe(32)

    return {
        "reset_token": token,
    }
